import {Pressable,Text,View} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";

/**
 * Labeled on/off row shared by the canvas settings panels: a 44pt switch with
 * the label on the start side and the track on the end side (mirrored in RTL).
 */
export function SettingSwitch({label,on,onChange,disabled,styled,hint}:{
  label:string;on:boolean;onChange:(on:boolean)=>void;disabled:boolean;styled:boolean;hint?:string|undefined;
}){
  return <Pressable role="switch" aria-checked={on} accessibilityRole="switch" accessibilityState={{checked:on,disabled}}
    aria-label={label} accessibilityHint={hint} disabled={disabled} onPress={()=>onChange(!on)}
    {...{className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{minHeight:44,flexDirection:"row",alignItems:"center",justifyContent:"space-between",gap:12,paddingHorizontal:4,opacity:disabled?0.5:1}}>
    <Text {...{className:joinClasses(styled&&"text-text text-sm")}} style={{flexShrink:1}}>{label}</Text>
    <View pointerEvents="none" {...{className:joinClasses(styled&&"border",styled&&(on?"bg-primary border-primary":"bg-surface-sunken border-border"))}}
      style={{width:40,height:24,borderRadius:12,padding:2,justifyContent:"center",alignItems:on?"flex-end":"flex-start"}}>
      <View {...{className:joinClasses(styled&&(on?"bg-on-primary":"bg-text-muted"))}} style={{width:18,height:18,borderRadius:9}}/>
    </View>
  </Pressable>;
}

import { Text, View, type ViewProps } from "react-native";
import { UnitInput } from "@/components/nyc-tron/ui/components/shell/UnitInput";
import { SettingSwitch } from "@/components/nyc-tron/ui/components/forge/canvas/SettingSwitch";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { validateHSLSecondary,type HSLSecondary } from "@/components/nyc-tron/ui/components/forge/color/color-adjustments";
export type { HSLSecondary } from "@/components/nyc-tron/ui/components/forge/color/color-adjustments";
/** Host-owned secondary selection and correction values. */
export interface HSLSecondaryEditorProps extends Omit<ViewProps,"children"> {readonly value:HSLSecondary;readonly onCommit:(value:HSLSecondary)=>void;readonly disabled?:boolean;readonly unstyled?:boolean}
/** Edits wrapping hue selection, saturation/luma bounds, mask refinement and corrections. */
export function HSLSecondaryEditor({value,onCommit,disabled=false,unstyled=false,...props}:HSLSecondaryEditorProps){
 validateHSLSecondary(value);
 const set=(change:Partial<HSLSecondary>)=>{if(disabled)return;const next={...value,...change};validateHSLSecondary(next);onCommit(next);};
 const fields=[['hueStart','Hue start degrees',0,360],['hueEnd','Hue end degrees',0,360],['hueFeather','Hue feather degrees',0,180],['saturationMin','Saturation minimum',0,value.saturationMax],['saturationMax','Saturation maximum',value.saturationMin,1],['luminanceMin','Luminance minimum',0,value.luminanceMax],['luminanceMax','Luminance maximum',value.luminanceMin,1],['softness','Mask softness',0,1],['denoise','Mask denoise',0,1],['hueShift','Hue shift degrees',-180,180],['saturationShift','Saturation correction',-1,1],['luminanceShift','Luminance correction',-1,1]] as const;
 return <View {...props} style={[{gap:8},props.style]}>
  <SettingSwitch label="Enable HSL secondary" on={value.enabled} onChange={enabled=>set({enabled})} disabled={disabled} styled={!unstyled}/>
  <Text {...{className:joinClasses(!unstyled&&"text-text-muted")}}>Hue start above end selects across zero degrees.</Text>
  {fields.map(([key,label,min,max])=><UnitInput key={key} label={label} value={value[key]} min={min} max={max} step={key.startsWith('hue')?1:.01} precision={4} disabled={disabled} unstyled={unstyled} onCommit={number=>set({[key]:number})}/>)}
  <SettingSwitch label="Show secondary mask" on={value.showMask} onChange={showMask=>set({showMask})} disabled={disabled} styled={!unstyled}/>
  <SettingSwitch label="Invert secondary mask" on={value.invert} onChange={invert=>set({invert})} disabled={disabled} styled={!unstyled}/>
 </View>;
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
